UPDATE t SET s = 'dddddddddddddddddddddddddddddddddddddddddddddddddd' WHERE x = 2;
SELECT x, CHAR_LENGTH(s) AS l, SUBSTRING(s FROM 1 FOR 1) AS f FROM t;
